INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bell-pit', 'west', 'the-dead-cart-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dead-cart-track', 'door', 'The Dead-Cart Track', 'Two deep ruts run west from the churchyard''s edge through the thorn, worn by wheels that went the one way loaded and came back light. Nothing else ever used this track, and nothing grows in the ruts even now. The thorn on either side leans away from it.', 0, 0, 'out', 0, -6, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-cart-track', 'east', 'the-bell-pit', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-cart-track', 'west', 'the-cart-tip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-cart-track', 'north', 'the-lime-pits', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-cart-track', 'south', 'the-plague-trench', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cart-tip', 'door', 'The Cart-Tip', 'The track ends at a lip of bare earth where the carts were backed up and tipped, and the ground falls away beyond it in a long slope of soil and bone. A broken axle lies half-buried at the edge. The slope is gnawed over from top to bottom, and the gnawing is fresh.', 0, 0, 'out', 0, -7, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-tip', 'east', 'the-dead-cart-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-tip', 'west', 'the-tipping-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-tip', 'north', 'the-bone-heaps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-tip', 'south', 'the-second-trench', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lime-pits', 'door', 'The Lime Pits', 'Square pits cut into the earth in a row, each one filled to the brim with something pale and crusted that is not chalk. The lime was meant to make the dead go faster and to keep things off them. It has done the first. Paw prints go round the edges of every pit and down into one of them.', 0, 0, 'out', 0, -6, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lime-pits', 'south', 'the-dead-cart-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lime-pits', 'west', 'the-bone-heaps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-plague-trench', 'door', 'The Plague Trench', 'A long straight trench, dug in a hurry and filled in a worse one, the earth heaped back over it in a ridge that has slumped into the shape of what is under it. Somebody pushed stakes in along its length to mark it as a place not to dig. Most of the stakes are down, and the ridge has been dug into all along its line.', 0, 0, 'out', 0, -6, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plague-trench', 'north', 'the-dead-cart-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plague-trench', 'west', 'the-second-trench', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plague-trench', 'south', 'the-burning-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tipping-edge', 'door', 'The Tipping Edge', 'The top of the long slope, where the ground breaks off into loose spill and you can see the whole of the pits laid out below and the gibbet on its hill beyond. The earth underfoot gives. Bones come up out of it after every rain, and something is always here first to take them.', 0, 0, 'out', 0, -8, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tipping-edge', 'east', 'the-cart-tip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tipping-edge', 'west', 'the-wash-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tipping-edge', 'north', 'the-gnawed-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tipping-edge', 'south', 'the-trench-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bone-heaps', 'door', 'The Bone Heaps', 'Mounds of bone raked together and left, grey and white, taller than a man in places and sliding in others. Whoever raked them stopped sorting and simply heaped. The heaps are tunnelled at the foot, and the tunnels are the width of a big dog.', 0, 0, 'out', 0, -7, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-heaps', 'east', 'the-lime-pits', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-heaps', 'south', 'the-cart-tip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-heaps', 'north', 'the-sorting-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-heaps', 'west', 'the-gnawed-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sorting-ground', 'door', 'The Sorting Ground', 'A stretch of trodden earth where somebody once laid the bones out in rows - long bones here, ribs there, skulls apart - before the numbers beat them. The rows are still faintly there under the scatter. The scatter is newer, and it has been dragged.', 0, 0, 'out', 0, -7, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorting-ground', 'south', 'the-bone-heaps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorting-ground', 'west', 'the-skull-mound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gnawed-ground', 'door', 'The Gnawed Ground', 'Bare earth trampled flat and littered end to end with split bone, cracked for the marrow and dropped. Everything here has been chewed, and the ground is printed over with the same broad, splayed tracks, crossing and recrossing. It smells of the pits and of something alive.', 0, 0, 'out', 0, -8, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-ground', 'east', 'the-bone-heaps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-ground', 'south', 'the-tipping-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-ground', 'west', 'the-den-mouths', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-ground', 'north', 'the-skull-mound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-trench', 'door', 'The Second Trench', 'A second trench beside the first, dug when the first was full, and never finished: it stops halfway along in a heap of thrown earth with a spade''s worth of bones on top of it. They were still digging when they gave it up. The open end is a ditch full of thorn.', 0, 0, 'out', 0, -7, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-trench', 'east', 'the-plague-trench', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-trench', 'north', 'the-cart-tip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-trench', 'west', 'the-trench-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-trench', 'south', 'the-ash-drifts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-burning-ground', 'door', 'The Burning Ground', 'A wide black scar in the earth where they burned the dead when there were too many even for the pits. Nothing has grown back on it. The ash has gone hard as a road, and charred ends of bone stand up out of it like stubble.', 0, 0, 'out', 0, -6, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burning-ground', 'north', 'the-plague-trench', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burning-ground', 'west', 'the-ash-drifts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-trench-end', 'door', 'The Trench End', 'Where the second trench runs out into the thorn, a low bank of spoil with the dead thorn grown down over it. The bank is hollowed underneath, and the hollow is lined with old fur and older bone. Something lies up here by day.', 0, 0, 'out', 0, -8, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-trench-end', 'east', 'the-second-trench', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-trench-end', 'north', 'the-tipping-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-trench-end', 'west', 'the-bone-fan', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ash-drifts', 'door', 'The Ash Drifts', 'The edge of the burning, where the ash was raked off and left in grey drifts against the thorn. The drifts have set into a crust that breaks underfoot onto something softer. The wind takes the dust off the top of it and lays it over everything.', 0, 0, 'out', 0, -7, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-drifts', 'east', 'the-burning-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-drifts', 'north', 'the-second-trench', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wash-gully', 'door', 'The Wash Gully', 'A gully cut by the rain down the face of the slope, bare-sided, with the water''s work showing in every layer: soil, bone, soil, bone, ash. The bottom of it is a bed of washed bones, white and clean. Things come down here to drink when it runs, and to dig when it doesn''t.', 0, 0, 'out', 0, -9, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wash-gully', 'east', 'the-tipping-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wash-gully', 'west', 'the-wash-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wash-gully', 'south', 'the-bone-fan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wash-gully', 'north', 'the-den-mouths', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-den-mouths', 'door', 'The Den Mouths', 'A bank of soft earth honeycombed with holes, each one big enough to take a hunched animal, each with a fan of spoil and gnawed bone spilling out of it. The ground in front of them is beaten bare. The holes are not empty. Some of them breathe.', 0, 0, 'out', 0, -9, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-den-mouths', 'east', 'the-gnawed-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-den-mouths', 'south', 'the-wash-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-den-mouths', 'north', 'the-laughing-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-den-mouths', 'west', 'the-dug-earth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wash-foot', 'door', 'The Wash Foot', 'The foot of the gully, where the rain drops what it carried in a broad fan of silt and bone spread out over the earth. The silt is printed thick with tracks going down to the wet and coming back. In the dry it cracks into plates, and the bones lie on top of the plates.', 0, 0, 'out', 0, -10, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wash-foot', 'east', 'the-wash-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wash-foot', 'north', 'the-dug-earth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bone-fan', 'door', 'The Bone Fan', 'A wide spill of bone and loose earth fanning out from the gully''s side, as if the slope had let go of everything at once. Bones of every size lie tangled in it, the big ones wedged and the small ones washed into the gaps. It shifts when you cross it.', 0, 0, 'out', 0, -9, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-fan', 'north', 'the-wash-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-fan', 'east', 'the-trench-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-laughing-ground', 'door', 'The Laughing Ground', 'An open patch of trodden earth among the den mouths, flattened by bodies lying on it and scattered with the remains of a great many meals. At night the sound carries from here across the whole of the pits, a high broken laughing that the gibbet hill sends back. It is a long way from funny.', 0, 0, 'out', 0, -9, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-laughing-ground', 'south', 'the-den-mouths', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-laughing-ground', 'east', 'the-skull-mound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dug-earth', 'door', 'The Dug Earth', 'Ground that has been dug over and over by claws, not spades, in hollows and scrapes that run into each other until there is no level ground at all. Bones turned up and dropped lie at the lip of every scrape. Whatever was buried shallow here has been found.', 0, 0, 'out', 0, -10, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dug-earth', 'east', 'the-den-mouths', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dug-earth', 'south', 'the-wash-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dug-earth', 'west', 'the-last-pit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-skull-mound', 'door', 'The Skull Mound', 'A mound built entirely of skulls, set there by hand course on course by somebody who sorted the dead and could not bear to leave the heads in the heap. It has been undermined at the foot and the lower courses have rolled. The ones that rolled have been gnawed.', 0, 0, 'out', 0, -8, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-skull-mound', 'east', 'the-sorting-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-skull-mound', 'south', 'the-gnawed-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-skull-mound', 'west', 'the-laughing-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-pit', 'door', 'The Last Pit', 'The last pit, at the far end of everything, dug and never filled. It is an open hole in the bare earth with the spoil thrown up round it, and in the bottom of it, among the thorn that has grown down into it, there are bones and fur and the leavings of meals. It is not a grave any more. It is a den.', 0, 0, 'out', 0, -11, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-pit', 'east', 'the-dug-earth', NULL);
